import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import './Navigation.css';

// Importar la imagen directamente
import logoImage from '../../public/images/logo_neto.png';

const Navigation: React.FC = () => {
  const location = useLocation();

  const navItems = [
    { path: '/', label: 'Inicio' },
    { path: '/bio', label: 'BIO' },
    { path: '/out-the-music', label: 'Out the music' },
    { path: '/contacto', label: 'Contact ▼' }
  ];

  return (
    <nav className="navigation">
      <div className="nav-container">
        <div className="logo-section">
          <div className="logo-icon">
            <img src={logoImage} alt="Neto Logo" className="logo-image" />
          </div>
          <div className="logo-text">
            <h1 className="logo-name">Adolfo Gutiérrez Arenas</h1>
          </div>
        </div>
        <ul className="nav-menu">
          {navItems.map((item) => (
            <li key={item.path} className="nav-item">
              <Link 
                to={item.path} 
                className={`nav-link ${location.pathname === item.path ? 'active' : ''}`}
              >
                {item.label}
              </Link>
            </li>
          ))}
        </ul>
      </div>
    </nav>
  );
};

export default Navigation;
